"""Duration calculations for distributed tracing spans."""

from collections.abc import Iterable, Mapping
from typing import Any

_FIELDS = ("trace_id", "span_id", "parent_id", "start_ns", "end_ns")


def exclusive_durations(spans: Iterable[Mapping[str, Any]]) -> dict[tuple[str, str], int]:
    """Return exclusive nanoseconds keyed by ``(trace_id, span_id)``."""
    records = list(spans)
    by_key: dict[tuple[str, str], Mapping[str, Any]] = {}
    for record in records:
        missing = [field for field in _FIELDS if field not in record]
        if missing:
            raise ValueError(f"span is missing required fields: {', '.join(missing)}")
        trace_id, span_id = record["trace_id"], record["span_id"]
        if not isinstance(trace_id, str) or not isinstance(span_id, str):
            raise TypeError("trace_id and span_id must be strings")
        if not isinstance(record["start_ns"], int) or not isinstance(record["end_ns"], int):
            raise TypeError("start_ns and end_ns must be integers")
        if record["end_ns"] < record["start_ns"]:
            raise ValueError(f"span {span_id!r} ends before it starts")
        key = (trace_id, span_id)
        if key in by_key:
            raise ValueError(f"duplicate span_id {span_id!r} in trace {trace_id!r}")
        by_key[key] = record

    children: dict[tuple[str, str], list[Mapping[str, Any]]] = {key: [] for key in by_key}
    for record in records:
        parent_id = record["parent_id"]
        if parent_id is None:
            continue
        if not isinstance(parent_id, str):
            raise TypeError("parent_id must be a string or None")
        parent_key = (record["trace_id"], parent_id)
        if parent_key not in by_key:
            raise ValueError(f"unknown parent_id {parent_id!r} in trace {record['trace_id']!r}")
        children[parent_key].append(record)

    result: dict[tuple[str, str], int] = {}
    for key, record in by_key.items():
        duration = record["end_ns"] - record["start_ns"]
        # BUG: raw summation double-counts overlap and out-of-parent time.
        child_time = sum(child["end_ns"] - child["start_ns"] for child in children[key])
        result[key] = duration - child_time
    return result

import unittest
from telemetry import exclusive_durations


class ExclusiveDurationTests(unittest.TestCase):
    def test_overlapping_children_are_counted_once(self):
        spans = [
            {"trace_id": "t", "span_id": "root", "parent_id": None, "start_ns": 0, "end_ns": 100},
            {"trace_id": "t", "span_id": "db", "parent_id": "root", "start_ns": 10, "end_ns": 60},
            {"trace_id": "t", "span_id": "cache", "parent_id": "root", "start_ns": 40, "end_ns": 80},
        ]
        durations = exclusive_durations(spans)
        self.assertEqual(durations[("t", "root")], 30)
        self.assertEqual(durations[("t", "db")], 50)
        self.assertEqual(durations[("t", "cache")], 40)

    def test_non_overlapping_tree_still_works(self):
        spans = [
            {"trace_id": "t", "span_id": "root", "parent_id": None, "start_ns": 0, "end_ns": 20},
            {"trace_id": "t", "span_id": "child", "parent_id": "root", "start_ns": 5, "end_ns": 11},
            {"trace_id": "t", "span_id": "leaf", "parent_id": "child", "start_ns": 7, "end_ns": 9},
        ]
        self.assertEqual(exclusive_durations(spans), {
            ("t", "root"): 14, ("t", "child"): 4, ("t", "leaf"): 2})


if __name__ == "__main__":
    unittest.main()
